local SaddlebagMaker = {}
local PRODUCTS = {
    iron_saddlebag = { name = "Železna sedlarna torba", ironCost = 1, woodCost = 1, leatherCost = 4, time = 5, cost = 165, prestige = 3, happiness = 2, description = "Železna sedlarna torba za osnovne potrebe." },
    bronze_saddlebag = { name = "Bronasta sedlarra torba", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 4, time = 7, cost = 400, prestige = 5, happiness = 3, description = "Bronasta sedlarna torba za lahko konjenico." },
    silver_saddlebag = { name = "Srebrna sedlarna torba", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 4, time = 11, cost = 970, prestige = 10, happiness = 4, description = "Srebrna sedlarna torba za plemiške konje." },
    gilded_saddlebag = { name = "Pozlačena sedlarna torba", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 4, time = 15, cost = 2100, prestige = 19, happiness = 5, description = "Pozlačena sedlarna torba za dvorne konje." },
    jewel_set_saddlebag = { name = "Draguljasta sedlarna torba", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 4, time = 19, cost = 4550, prestige = 35, happiness = 7, description = "Draguljasta sedlarna torba za kraljeve konje." },
    royal_sovereign_saddlebag = { name = "Kraljevski suverena sedlarna torba", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 5, time = 26, cost = 9700, prestige = 67, happiness = 13, description = "Suverena sedlarna torba z biseri za krono." },
}
local BUILDINGS = {
    saddlebag_workshop = { name = "Torbarska delavnica", cost = { gold = 320, wood = 170, stone = 130, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    saddlebag_house = { name = "Torbarska hiša", cost = { gold = 1180, wood = 350, stone = 260, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_saddlebag_atelier = { name = "Mojstrski torbarski atelje", cost = { gold = 2960, wood = 410, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_saddlebag_palace = { name = "Suverena torbarska palača", cost = { gold = 12850, wood = 625, stone = 825, gold = 82, jewel = 19 }, upkeep = 251, qualityBonus = 55, prestigeBonus = 50 },
}
SaddlebagMaker.ironStock = 10; SaddlebagMaker.bronzeStock = 8; SaddlebagMaker.woodStock = 12; SaddlebagMaker.leatherStock = 16; SaddlebagMaker.silverStock = 8; SaddlebagMaker.goldStock = 6; SaddlebagMaker.jewelStock = 4; SaddlebagMaker.pearlStock = 4
SaddlebagMaker.productStock = {}; SaddlebagMaker.buildings = {}; SaddlebagMaker.maker = nil; SaddlebagMaker.activeMaking = {}; SaddlebagMaker.totalProducts = 0; SaddlebagMaker.dayTimer = 0
function SaddlebagMaker.init() SaddlebagMaker.ironStock=10; SaddlebagMaker.bronzeStock=8; SaddlebagMaker.woodStock=12; SaddlebagMaker.leatherStock=16; SaddlebagMaker.silverStock=8; SaddlebagMaker.goldStock=6; SaddlebagMaker.jewelStock=4; SaddlebagMaker.pearlStock=4; SaddlebagMaker.productStock={}; SaddlebagMaker.buildings={}; SaddlebagMaker.maker=nil; SaddlebagMaker.activeMaking={}; SaddlebagMaker.totalProducts=0; SaddlebagMaker.dayTimer=0; print("[SaddlebagMaker] Royal Saddlebag Maker System initialized (6 products, 4 buildings)") end
function SaddlebagMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaddlebagMaker.maker={name=n or ("Torbar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Torbar najet: %s (spretnost: %d)",SaddlebagMaker.maker.name,s),"success") end; return true end
function SaddlebagMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaddlebagMaker.build(id) local ok,e=SaddlebagMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaddlebagMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaddlebagMaker.getQualityBonus() local b=0; for _,bd in ipairs(SaddlebagMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaddlebagMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SaddlebagMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SaddlebagMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SaddlebagMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SaddlebagMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SaddlebagMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaddlebagMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaddlebagMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SaddlebagMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SaddlebagMaker.buildings==0 then return false,"Potrebna torbarska delavnica" end; if not SaddlebagMaker.maker then return false,"Potreben torbar" end; return true end
function SaddlebagMaker.make(pt,qty) qty=qty or 1; local ok,e=SaddlebagMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SaddlebagMaker.ironStock=SaddlebagMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SaddlebagMaker.bronzeStock=SaddlebagMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SaddlebagMaker.woodStock=SaddlebagMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SaddlebagMaker.leatherStock=SaddlebagMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SaddlebagMaker.silverStock=SaddlebagMaker.silverStock-d.silverCost*qty end; if d.goldCost then SaddlebagMaker.goldStock=SaddlebagMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SaddlebagMaker.jewelStock=SaddlebagMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SaddlebagMaker.pearlStock=SaddlebagMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SaddlebagMaker.maker then t=math.max(1,t-math.floor(SaddlebagMaker.maker.skill/13)) end; table.insert(SaddlebagMaker.activeMaking,{id="saddlebag_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaddlebagMaker.completeMaking(m) local q=1.0+(SaddlebagMaker.getQualityBonus()/100); if SaddlebagMaker.maker then q=q+(SaddlebagMaker.maker.skill/140) end; q=math.min(2.5,q); SaddlebagMaker.productStock[m.productType]=(SaddlebagMaker.productStock[m.productType] or 0)+m.quantity; SaddlebagMaker.totalProducts=SaddlebagMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaddlebagMaker.maker then SaddlebagMaker.maker.itemsMade=SaddlebagMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SaddlebagMaker.maker.skill=math.min(100,SaddlebagMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Torba izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saddlebag.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SaddlebagMaker.update(dt) if not _G.state then return end; SaddlebagMaker.dayTimer=SaddlebagMaker.dayTimer+dt; if SaddlebagMaker.dayTimer>=30 then SaddlebagMaker.dayTimer=0; for i=#SaddlebagMaker.activeMaking,1,-1 do local m=SaddlebagMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaddlebagMaker.completeMaking(m); table.remove(SaddlebagMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaddlebagMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaddlebagMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaddlebagMaker.getStats() return {ironStock=SaddlebagMaker.ironStock,bronzeStock=SaddlebagMaker.bronzeStock,woodStock=SaddlebagMaker.woodStock,leatherStock=SaddlebagMaker.leatherStock,silverStock=SaddlebagMaker.silverStock,goldStock=SaddlebagMaker.goldStock,jewelStock=SaddlebagMaker.jewelStock,pearlStock=SaddlebagMaker.pearlStock,productStock=SaddlebagMaker.productStock,numBuildings=#SaddlebagMaker.buildings,hasMaker=SaddlebagMaker.maker~=nil,makerName=SaddlebagMaker.maker and SaddlebagMaker.maker.name or "—",makerSkill=SaddlebagMaker.maker and SaddlebagMaker.maker.skill or 0,activeMaking=#SaddlebagMaker.activeMaking,totalProducts=SaddlebagMaker.totalProducts} end
return SaddlebagMaker
